mapper.select:
select PERIOD_ID
from TBL_PERIOD
where YEAR = #{year} and MONTH = #{month}

select count(AGGREGATE_ID)
from TBL_PERIOD_AGGREGATE
where USER_ID = #{userId} and PERIOD_ID = #{periodId}

mapper.update:
update TBL_PERIOD_AGGREGATE
set INCOME_SUM = (select INCOME_SUM
                  from TBL_PERIOD_AGGREGATE
                  where USER_ID = #{userId} and PERIOD_ID = #{periodId}) + #{additionalIncome}
where USER_ID = #{userId} and PERIOD_ID = #{periodId}

update TBL_PERIOD_AGGREGATE
set PLANNED_EXPENSE_SUM =
        (select PLANNED_EXPENSE_SUM
         from TBL_PERIOD_AGGREGATE
         where USER_ID = #{userId}
           and PERIOD_ID = #{periodId})
            - #{oldBudgetAmount}
            + #{newBudgetAmount}
where USER_ID = #{userId} and PERIOD_ID = #{periodId}

mapper.select:
select AVAILABLE_AMOUNT
from TBL_PERIOD_AGGREGATE
where USER_ID = #{userId} and PERIOD_ID =#{periodId}

select aggregate_id, user_id, period_id, income_sum, planned_expense_sum, actual_expense_sum, available_amount, update_at
from TBL_PERIOD_AGGREGATE
where USER_ID = #{userId} and PERIOD_ID =#{periodId}
